application.css:
@import url('https://fonts.googleapis.com/css2?family=DM+Sans:wght@400;500;700&family=Space+Grotesk:wght@500;700&display=swap');

:root { --ink:#172033; --muted:#718096; --line:#e3e9f2; --blue:#4867e8; --mint:#e9f8f1; }
* { box-sizing:border-box; }
body { margin:0; min-height:100vh; color:var(--ink); font-family:'DM Sans',sans-serif; background:linear-gradient(135deg,#f5f8ff 0%,#eef8f5 100%); }
.page-shell { max-width:850px; margin:0 auto; padding:54px 20px 30px; }
.quiz-card { background:#fff; border:1px solid rgba(220,228,240,.8); border-radius:24px; box-shadow:0 20px 60px rgba(44,65,110,.12); overflow:hidden; }
.quiz-header { padding:42px 48px 30px; background:linear-gradient(110deg,#f4f6ff,#fbfffd); border-bottom:1px solid var(--line); }
.eyebrow { color:var(--blue); font-size:11px; font-weight:700; letter-spacing:2px; margin-bottom:12px; }
h1 { font:700 38px 'Space Grotesk',sans-serif; letter-spacing:-1.5px; margin:0 0 9px; }
.quiz-header p { color:var(--muted); margin:0; font-size:15px; }
.questions { padding:26px 48px 4px; }
.question { border:0; border-bottom:1px solid var(--line); padding:0 0 25px; margin:0 0 25px; min-width:0; }
.question:last-child { margin-bottom:0; }
legend { display:flex; gap:14px; align-items:flex-start; width:100%; padding:0; font:700 18px 'Space Grotesk',sans-serif; line-height:1.4; }
.question-number { color:var(--blue); font-size:12px; letter-spacing:1px; padding-top:4px; }
.options { display:grid; grid-template-columns:repeat(3,1fr); gap:10px; margin:18px 0 0 31px; }
.option { position:relative; display:flex; align-items:center; gap:10px; border:1px solid var(--line); border-radius:10px; padding:13px 14px; color:#526075; cursor:pointer; font-size:14px; transition:.2s ease; }
.option:hover { border-color:#9caff6; background:#f8f9ff; transform:translateY(-1px); }
.option input { position:absolute; opacity:0; pointer-events:none; }
.radio-mark { width:16px; height:16px; flex:none; border:2px solid #c6cfdd; border-radius:50%; position:relative; }
.option:has(input:checked) { border-color:var(--blue); background:#f2f4ff; color:#253b9c; box-shadow:0 4px 12px rgba(72,103,232,.1); }
.option:has(input:checked) .radio-mark { border-color:var(--blue); }
.option:has(input:checked) .radio-mark:after { content:''; width:7px; height:7px; background:var(--blue); border-radius:50%; position:absolute; top:2.5px; left:2.5px; }
.actions { padding:24px 48px 30px; display:flex; align-items:center; gap:18px; }
button { border:0; border-radius:10px; padding:14px 22px; background:var(--blue); color:#fff; font:700 14px 'DM Sans',sans-serif; cursor:pointer; box-shadow:0 7px 15px rgba(72,103,232,.22); transition:.2s; }
button:hover { background:#3855cf; transform:translateY(-2px); } button span { font-size:19px; margin-left:8px; vertical-align:-1px; }
.message { color:#d05b61; font-size:13px; margin:0; }
.result { margin:0 48px 42px; padding:24px; border-radius:15px; background:var(--mint); text-align:center; }
.result-label { color:#4c8e75; font-size:10px; font-weight:700; letter-spacing:2px; }
.score { color:#227257; font:700 42px 'Space Grotesk',sans-serif; min-height:50px; }
.result-copy { color:#5e8878; font-size:13px; }
footer { text-align:center; color:#8a98aa; font-size:12px; margin-top:22px; }
@media (max-width:650px) { .page-shell{padding:20px 12px}.quiz-header{padding:30px 24px}.questions{padding:25px 24px 0}.actions{padding:20px 24px 25px;display:block}.message{margin-top:12px}.result{margin:0 24px 28px}h1{font-size:31px}.options{grid-template-columns:1fr;margin-left:0} }

application.javascript:
const form = document.getElementById('quiz-form');
const scoreElement = document.querySelector('[data-testid="quiz-score"]');
const message = document.getElementById('message');
const resultCopy = document.getElementById('result-copy');
const answers = { q1: 'mars', q2: 'pacific', q3: 'six' };

form.addEventListener('submit', function (event) {
  event.preventDefault();
  const formData = new FormData(form);
  const selected = ['q1', 'q2', 'q3'].map(name => formData.get(name));
  if (selected.some(answer => !answer)) {
    message.textContent = 'Please choose one answer for each question.';
    return;
  }
  message.textContent = '';
  const score = selected.reduce((total, answer, index) => {
    return total + (answer === answers['q' + (index + 1)] ? 1 : 0);
  }, 0);
  scoreElement.textContent = score + ' / 3';
  scoreElement.dataset.score = String(score);
  resultCopy.textContent = score === 3 ? 'Perfect score — excellent work!' : score === 0 ? 'Good try — now you know what to revisit.' : 'Nice work — keep building your knowledge.';
});
